window.__GLOSSARY__ = {"arc":{"term":"Arc<T>","aliases":["Arc","Arc<Mutex<T>>","Arc<Mutex<Inner>>"],"short":"Atomically reference-counted shared pointer. Cloning it bumps a refcount and hands back a second owner of the same value, not a copy.","why":"Lets two threads or tasks own one value at once. It is how a detached task can touch state the spawner still holds.","prereqs":["ownership","move","send-sync"],"link":{"label":"Rust Book 16.3","url":"https://doc.rust-lang.org/book/ch16-03-shared-state.html"}},"mutex":{"term":"Mutex<T>","aliases":["Mutex"],"short":"A lock guarding interior data so only one holder mutates at a time. tokio's async Mutex yields the thread while waiting instead of blocking it.","why":"Shared ownership alone still races on writes. The Mutex is what makes the shared mutation safe, checked at compile time.","prereqs":["ownership","send-sync"],"link":{"label":"Rust Book 16.3","url":"https://doc.rust-lang.org/book/ch16-03-shared-state.html"}},"ownership":{"term":"ownership","aliases":[],"short":"Every value has exactly one owner; when the owner goes out of scope the value is dropped. No garbage collector, no manual free.","why":"The single-owner rule is the root of Rust's memory safety and the reason sharing has to be made explicit.","prereqs":[],"link":{"label":"Rust Book 4.1","url":"https://doc.rust-lang.org/book/ch04-01-what-is-ownership.html"}},"move":{"term":"move","aliases":["move semantics"],"short":"Assigning or passing a non-Copy value transfers ownership; the source can no longer be used. `move` on a closure forces it to own its captures.","why":"A spawned task must own what it touches. `move` is how you hand ownership into it so it can outlive the caller.","prereqs":["ownership"],"link":{"label":"Rust Book 4.1","url":"https://doc.rust-lang.org/book/ch04-01-what-is-ownership.html#variables-and-data-interacting-with-move"}},"send-sync":{"term":"Send / Sync","aliases":["Send","Sync","Send + Sync"],"short":"Marker traits the compiler infers: Send means a value can move to another thread; Sync means it can be shared by reference across threads.","why":"They are what let the compiler reject data races before the program runs. Arc is Send/Sync; Rc is not.","prereqs":["ownership"],"link":{"label":"Rust Book 16.4","url":"https://doc.rust-lang.org/book/ch16-04-extensible-concurrency-sync-and-send.html"}}};
